<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Protótipo Navegável — A Seleção (exp07ef1b)</title>
  <style>
    :root {
      /* Nove tokens obrigatórios do Design System Unooria / wireframe-cinza */
      --superficie-base: #FFFFFF;
      --superficie-elevada: #FAFAFA;
      --superficie-midia: #E0E0E0;
      --borda-padrao: #C7C7C7;
      --borda-foco: #1A1A1A;
      --texto-primario: #1A1A1A;
      --texto-secundario: #6B6B6B;
      --acao-primaria: #1A1A1A;
      --acao-secundaria: #EDEDED;

      /* Casca da ferramenta de revisão humana (único lugar com identidade visual da ferramenta) */
      --shell-bg: #121820;
      --shell-sidebar: #1A222D;
      --shell-border: #2D3A4B;
      --shell-text: #E2E8F0;
      --shell-text-muted: #94A3B8;
      --shell-accent: #38BDF8;
      --shell-pico: #EF4444;
      --shell-aha: #F59E0B;
      --shell-docente: #6366F1;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: var(--shell-bg);
      color: var(--shell-text);
      height: 100vh;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    /* BARRA SUPERIOR DA CASCA DE REVISÃO */
    header.review-bar {
      height: 52px;
      background: var(--shell-sidebar);
      border-bottom: 1px solid var(--shell-border);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 16px;
      flex-shrink: 0;
      min-width: 0;
    }

    .review-bar-left {
      display: flex;
      align-items: center;
      gap: 12px;
      min-width: 0;
    }

    .mission-title {
      font-weight: 700;
      font-size: 15px;
      color: #FFF;
      white-space: nowrap;
    }

    .stage-badge {
      font-size: 12px;
      padding: 3px 8px;
      border-radius: 4px;
      background: #2A3649;
      color: var(--shell-accent);
      font-weight: 600;
      white-space: nowrap;
    }

    .mark-tag {
      font-size: 11px;
      padding: 2px 6px;
      border-radius: 4px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    .mark-pico { background: rgba(239, 68, 68, 0.2); color: #F87171; border: 1px solid #EF4444; }
    .mark-aha { background: rgba(245, 158, 11, 0.2); color: #FBBF24; border: 1px solid #F59E0B; }
    .mark-latch { background: rgba(148, 163, 184, 0.2); color: #CBD5E1; border: 1px solid #94A3B8; }
    .mark-docente { background: rgba(99, 102, 241, 0.2); color: #A5B4FC; border: 1px solid #6366F1; }

    .review-bar-right {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .counter-label {
      font-size: 13px;
      color: var(--shell-text-muted);
      font-variant-numeric: tabular-nums;
    }

    .nav-btn {
      background: #243040;
      border: 1px solid var(--shell-border);
      color: #FFF;
      padding: 5px 12px;
      border-radius: 4px;
      cursor: pointer;
      font-size: 13px;
      font-weight: 600;
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .nav-btn:hover { background: #2F3E52; }
    .nav-btn:focus-visible { outline: 2px solid var(--shell-accent); }

    /* LAYOUT PRINCIPAL: 3 COLUNAS */
    .workspace {
      display: flex;
      flex: 1;
      height: calc(100vh - 52px - 60px);
      min-width: 0;
      overflow: hidden;
    }

    /* COLUNA 1: TRILHO À ESQUERDA */
    nav.review-rail {
      width: 280px;
      background: var(--shell-sidebar);
      border-right: 1px solid var(--shell-border);
      overflow-y: auto;
      overflow-x: hidden;
      flex-shrink: 0;
      min-width: 0;
      padding: 12px 8px;
    }

    .rail-group {
      margin-bottom: 16px;
    }

    .rail-group-title {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--shell-text-muted);
      padding: 4px 8px;
      font-weight: 700;
    }

    .rail-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 10px;
      margin-bottom: 2px;
      border-radius: 6px;
      cursor: pointer;
      color: var(--shell-text);
      text-decoration: none;
      font-size: 13px;
      border: 1px solid transparent;
      min-width: 0;
    }
    .rail-item:hover { background: #232D3B; }
    .rail-item:focus-visible { outline: 2px solid var(--shell-accent); }
    .rail-item.active {
      background: #263445;
      border-color: var(--shell-accent);
      color: #FFF;
      font-weight: 600;
    }

    .rail-item-info {
      display: flex;
      flex-direction: column;
      min-width: 0;
    }
    .rail-item-id {
      font-family: monospace;
      font-size: 11px;
      color: var(--shell-text-muted);
    }
    .rail-item.active .rail-item-id { color: var(--shell-accent); }
    .rail-item-title {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .rail-badge-docente {
      font-size: 9px;
      background: #3730A3;
      color: #C7D2FE;
      padding: 2px 4px;
      border-radius: 3px;
      font-weight: 700;
      flex-shrink: 0;
    }

    /* COLUNA 2: PALCO CENTRAL */
    main.stage-container {
      flex: 1;
      background: #0B0F14;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 16px;
      min-width: 0;
      overflow: hidden;
      position: relative;
    }

    .stage-wrapper {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      max-height: 100%;
      min-width: 0;
    }

    /* MOLDURA DE DISPOSITIVO: DESKTOP HUB EMBED (CELULAR VERTICAL 375x812) */
    .device-mobile-frame {
      width: 375px;
      height: 680px; /* adaptado verticalmente com scroll interno mantendo viewport 375 */
      max-height: 75vh;
      background: var(--superficie-base);
      border: 8px solid #334155;
      border-radius: 28px;
      box-shadow: 0 20px 40px rgba(0,0,0,0.6);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      position: relative;
    }

    /* MOLDURA DE DISPOSITIVO: DESKTOP CHEIO (1366x768 simulado no stage) */
    .device-desktop-frame {
      width: 680px;
      height: 440px;
      max-height: 75vh;
      background: var(--superficie-base);
      border: 4px solid #334155;
      border-radius: 8px;
      box-shadow: 0 20px 40px rgba(0,0,0,0.6);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      position: relative;
    }

    .frame-legend {
      font-size: 11px;
      color: var(--shell-text-muted);
      margin-top: 8px;
      text-align: center;
      font-family: monospace;
    }

    /* CONTEÚDO DOS QUADROS LO-FI (ESTRITAMENTE DENTRO DOS 9 TOKENS) */
    .screen-quadro {
      flex: 1;
      width: 100%;
      height: 100%;
      background: var(--superficie-base);
      color: var(--texto-primario);
      display: flex;
      flex-direction: column;
      overflow-y: auto;
      overflow-x: hidden;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      position: relative;
    }

    /* Elementos Lo-Fi do Instagram Simulado (instanooria) */
    .insta-topbar {
      height: 44px;
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      background: var(--superficie-base);
      flex-shrink: 0;
    }
    .insta-username {
      font-weight: 700;
      font-size: 14px;
      color: var(--texto-primario);
    }
    .insta-badge-saved {
      font-size: 12px;
      color: var(--texto-secundario);
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      padding: 2px 8px;
      border-radius: 12px;
      font-weight: 600;
    }

    .insta-bottombar {
      height: 48px;
      border-top: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-around;
      background: var(--superficie-base);
      flex-shrink: 0;
    }
    .bottom-icon {
      font-size: 11px;
      font-weight: 600;
      color: var(--texto-secundario);
      text-transform: uppercase;
      padding: 4px;
    }
    .bottom-icon.active {
      color: var(--texto-primario);
      font-weight: 700;
      border-bottom: 2px solid var(--borda-foco);
    }

    /* Card de Post no Feed */
    .post-card {
      border-bottom: 1px solid var(--borda-padrao);
      padding-bottom: 12px;
      margin-bottom: 8px;
      background: var(--superficie-base);
    }
    .post-header {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
    }
    .avatar-circle {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 10px;
      font-weight: 700;
      color: var(--texto-secundario);
      flex-shrink: 0;
    }
    .post-user {
      font-size: 13px;
      font-weight: 700;
    }
    .media-box-lofi {
      width: 100%;
      aspect-ratio: 1 / 1;
      background: var(--superficie-midia);
      border-top: 1px solid var(--borda-padrao);
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      position: relative;
      padding: 16px;
      text-align: center;
    }
    .media-box-x {
      font-size: 48px;
      color: var(--borda-padrao);
      font-weight: 200;
      line-height: 1;
      margin-bottom: 8px;
      user-select: none;
    }
    .media-box-desc {
      font-size: 11px;
      color: var(--texto-secundario);
      line-height: 1.3;
    }
    .post-actions {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 12px 4px 12px;
    }
    .action-group {
      display: flex;
      gap: 12px;
    }
    .action-btn {
      background: none;
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      padding: 4px 8px;
      font-size: 11px;
      font-weight: 600;
      color: var(--texto-primario);
      cursor: pointer;
    }
    .action-btn.saved-active {
      background: var(--acao-primaria);
      color: var(--superficie-base);
      border-color: var(--borda-foco);
    }
    .post-caption {
      padding: 0 12px;
      font-size: 13px;
      line-height: 1.4;
      color: var(--texto-primario);
    }
    .post-caption strong {
      font-weight: 700;
    }

    /* Modal diegético / Overlay */
    .dm-modal-overlay {
      position: absolute;
      inset: 0;
      background: rgba(0,0,0,0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 16px;
      z-index: 10;
    }
    .dm-modal-card {
      background: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 12px;
      width: 100%;
      max-width: 320px;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .dm-header {
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .dm-bubble {
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      padding: 12px;
      font-size: 13px;
      line-height: 1.4;
      color: var(--texto-primario);
    }
    .btn-primary-lofi {
      background: var(--acao-primaria);
      color: var(--superficie-base);
      border: 1px solid var(--borda-foco);
      padding: 10px 14px;
      border-radius: 6px;
      font-weight: 600;
      font-size: 13px;
      text-align: center;
      cursor: pointer;
      display: block;
      width: 100%;
    }
    .btn-primary-lofi:focus-visible {
      outline: 2px solid var(--borda-foco);
    }

    .btn-secondary-lofi {
      background: var(--acao-secundaria);
      color: var(--texto-primario);
      border: 1px solid var(--borda-padrao);
      padding: 8px 12px;
      border-radius: 6px;
      font-weight: 600;
      font-size: 13px;
      text-align: center;
      cursor: pointer;
    }

    /* Mosaico da Aba Salvos */
    .mosaic-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 4px;
      padding: 8px;
      background: var(--superficie-elevada);
    }
    .mosaic-item {
      aspect-ratio: 1 / 1;
      background: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      position: relative;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 10px;
      text-align: center;
      padding: 4px;
    }
    .mosaic-item.selected {
      border: 4px solid var(--borda-foco);
    }
    .mosaic-check {
      position: absolute;
      top: 4px;
      right: 4px;
      background: var(--borda-foco);
      color: var(--superficie-base);
      font-size: 9px;
      font-weight: 700;
      width: 16px;
      height: 16px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    /* Composer de Stories */
    .story-composer {
      padding: 12px;
      border-top: 1px solid var(--borda-padrao);
      background: var(--superficie-base);
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .composer-badge {
      font-size: 12px;
      font-weight: 700;
      color: var(--texto-primario);
      display: flex;
      justify-content: space-between;
    }
    .composer-textarea {
      width: 100%;
      height: 64px;
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      padding: 8px;
      font-size: 12px;
      font-family: inherit;
      resize: none;
      background: var(--superficie-elevada);
      color: var(--texto-primario);
    }
    .composer-textarea:focus {
      outline: 2px solid var(--borda-foco);
      background: var(--superficie-base);
    }

    /* Visualizador de Stories (E4 - Pico / Aha) */
    .story-viewer {
      flex: 1;
      background: var(--superficie-elevada);
      display: flex;
      flex-direction: column;
      position: relative;
    }
    .story-progress-bar {
      display: flex;
      gap: 4px;
      padding: 8px 12px 4px 12px;
    }
    .story-seg {
      flex: 1;
      height: 3px;
      background: var(--borda-padrao);
      border-radius: 2px;
    }
    .story-seg.filled { background: var(--borda-foco); }

    .story-user-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 4px 12px 8px 12px;
    }
    .story-tabs {
      display: flex;
      gap: 8px;
    }
    .story-tab-btn {
      font-size: 11px;
      font-weight: 700;
      padding: 4px 8px;
      border-radius: 4px;
      border: 1px solid var(--borda-padrao);
      background: var(--superficie-base);
      cursor: pointer;
    }
    .story-tab-btn.active {
      background: var(--acao-primaria);
      color: var(--superficie-base);
      border-color: var(--borda-foco);
    }

    .story-media-full {
      flex: 1;
      background: var(--superficie-midia);
      border-top: 1px solid var(--borda-padrao);
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 20px;
      text-align: center;
      position: relative;
    }

    .story-caption-overlay {
      position: absolute;
      bottom: 12px;
      left: 12px;
      right: 12px;
      background: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      padding: 10px;
      border-radius: 6px;
      font-size: 12px;
      line-height: 1.3;
      color: var(--texto-primario);
    }

    /* Gaveta de Metadados / Ficha Técnica (E4-ALU-02 Aha) */
    .meta-drawer {
      border-top: 2px solid var(--borda-foco);
      background: var(--superficie-base);
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .drawer-title {
      font-size: 12px;
      font-weight: 700;
      color: var(--texto-primario);
    }
    .tags-container {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
    }
    .tag-pill {
      font-size: 11px;
      font-weight: 600;
      padding: 3px 8px;
      border-radius: 12px;
      border: 1px solid var(--borda-padrao);
      background: var(--superficie-elevada);
      color: var(--texto-primario);
    }
    .tag-pill.tag-active {
      border: 2px solid var(--borda-foco);
      background: var(--acao-secundaria);
    }

    .radar-chart-lofi {
      display: flex;
      flex-direction: column;
      gap: 4px;
      margin-top: 4px;
    }
    .radar-bar-row {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 11px;
    }
    .radar-bar-label { width: 90px; text-align: right; color: var(--texto-secundario); }
    .radar-bar-track { flex: 1; height: 8px; background: var(--superficie-midia); border-radius: 4px; overflow: hidden; }
    .radar-bar-fill { height: 100%; background: var(--acao-primaria); }

    /* Tela Unooria Institucional (E6 - Refletir) */
    .unooria-header {
      padding: 12px;
      background: var(--superficie-elevada);
      border-bottom: 1px solid var(--borda-padrao);
    }
    .unooria-title { font-size: 14px; font-weight: 700; }
    .unooria-card {
      margin: 12px;
      padding: 12px;
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .prompt-text {
      font-size: 12px;
      line-height: 1.45;
      color: var(--texto-primario);
    }

    /* Carrossel de Explicação (E5) */
    .carousel-card {
      margin: 16px;
      padding: 16px;
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      background: var(--superficie-elevada);
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .carousel-dots {
      display: flex;
      justify-content: center;
      gap: 6px;
      margin: 8px 0;
    }
    .dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--borda-padrao);
    }
    .dot.active { background: var(--borda-foco); }

    /* Rodapé interno obrigatório de 11px em cada tela */
    .internal-state-note {
      font-size: 11px;
      color: var(--texto-secundario);
      padding: 6px 12px;
      border-top: 1px solid var(--borda-padrao);
      background: var(--superficie-elevada);
      text-align: center;
      font-family: monospace;
      flex-shrink: 0;
    }

    /* COLUNA 3: PAINEL DA ETAPA (POR QUÊ / ONE-PAGER LITERAL) */
    aside.stage-panel {
      width: 370px;
      background: var(--shell-sidebar);
      border-left: 1px solid var(--shell-border);
      overflow-y: auto;
      overflow-x: hidden;
      flex-shrink: 0;
      min-width: 0;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .panel-header {
      border-bottom: 1px solid var(--shell-border);
      padding-bottom: 10px;
    }
    .panel-stage-name {
      font-size: 16px;
      font-weight: 700;
      color: #FFF;
      margin-bottom: 4px;
    }
    .panel-actor {
      font-size: 12px;
      color: var(--shell-accent);
      font-weight: 600;
    }

    .panel-block {
      display: flex;
      flex-direction: column;
      gap: 6px;
    }
    .panel-label {
      font-size: 13px;
      font-weight: 700;
      color: var(--shell-text-muted);
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    .panel-body {
      font-size: 14px;
      line-height: 1.5;
      color: var(--shell-text);
      word-break: break-word;
    }

    .panel-source-line {
      margin-top: auto;
      padding-top: 12px;
      border-top: 1px solid var(--shell-border);
      font-size: 13px;
      color: var(--shell-text-muted);
      font-style: italic;
    }

    /* RODAPÉ DA CASCA DE REVISÃO */
    footer.review-footer {
      height: 60px;
      background: var(--shell-sidebar);
      border-top: 1px solid var(--shell-border);
      display: flex;
      align-items: center;
      padding: 0 16px;
      gap: 24px;
